using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed discriminator from "Discriminator" to "$type".
            // Preserve compatibility with existing 500K documents written by EF Core 8.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Preserve the legacy format so existing documents remain readable.
            entity.HasIdProperty("id");
            entity.Property<string>("__id")
                  .ToJsonProperty("id");
            // Use the legacy id generation to keep "Product|<key>" format.
            entity.Property(p => p.Id).ToJsonProperty("Id");
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 removes sync I/O for Cosmos. No configuration needed here,
        // but all queries must use async APIs (see CosmosQuery.cs).
    }
}
