using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: Discriminator property renamed "$type" in EF Core 9.
            // Opt back into legacy name so existing documents and raw SQL queries work.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // BREAKING CHANGE 2: Id format changed from "Product|123" to "123".
            // Opt back into legacy format for compatibility with 500K existing docs.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion<string>()
                  .ToJsonProperty("id");

            // BREAKING CHANGE 3: HasIndex() is not supported on Cosmos (was no-op in 8, throws in 9).
            // Removed the HasIndex(p => p.Sku) call.
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

